1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const WHOLE_PERCENT = 100;
71	
72	const percentOf = (amount: number, percent: number): number =>
73	  (amount * percent) / WHOLE_PERCENT;
74	
75	const itemBasePremium = (item: Item): number =>
76	  BASE_PREMIUM_BY_TYPE[item.type];
77	
78	const BLOCK_SIZE = 3;
79	
80	const BLOCK_PREMIUM = 60;
81	
82	const sumOf = (amounts: number[]): number =>
83	  amounts.reduce((sum, amount) => sum + amount, 0);
84	
85	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
86	
87	const sumOfItemBasePremiums = (items: Item[]): number =>
88	  sumOf(items.map(itemBasePremium));
89	
90	// Items of the same type are "alike" and are priced together, so the policy
91	// base premium is computed group by group rather than item by item.
92	const alikeGroups = (items: Item[]): Item[][] => {
93	  const groupsByType = new Map<string, Item[]>();
94	
95	  for (const item of items) {
96	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
97	  }
98	
99	  return [...groupsByType.values()];
100	};
101	
102	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
103	  formsABlock(alikeItems)
104	    ? BLOCK_PREMIUM
105	    : sumOfItemBasePremiums(alikeItems);
106	
107	const policyBasePremium = (items: Item[]): number =>
108	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
109	
110	const roundPremiumInMHPCOsFavor = (amount: number): number =>
111	  Math.ceil(amount);
112	
113	// The inputs a single quote is computed from: `items` drives the base premium
114	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
115	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
116	// general — a claim step is not a contract and must not trigger the follow-up
117	// discount.
118	type QuoteRequest = {
119	  customer: Customer;
120	  items: Item[];
121	  precedingQuoteCount: number;
122	};
123	
124	const LOYALTY_YEARS = 2;
125	
126	const LOYALTY_DISCOUNT_PERCENT = 20;
127	
128	// Modifier percents are signed so surcharges and discounts can be summed
129	// uniformly; a discount enters the sum as its negation.
130	const asDiscount = (percent: number): number => -percent;
131	
132	const isLoyal = (customer: Customer): boolean =>
133	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
134	
135	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
136	
137	const isFollowUpContract = (request: QuoteRequest): boolean =>
138	  request.precedingQuoteCount > 0;
139	
140	const policyModifierPercents = (request: QuoteRequest): number[] => [
141	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
142	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
143	  ...(isFollowUpContract(request)
144	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
145	    : []),
146	];
147	
148	// Policy-wide modifiers do NOT compound: each is an independent percentage of
149	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
150	// would give a different, wrong answer.
151	const applyPolicyModifiers = (
152	  basePremium: number,
153	  request: QuoteRequest,
154	): number =>
155	  basePremium +
156	  sumOf(
157	    policyModifierPercents(request).map((percent) =>
158	      percentOf(basePremium, percent),
159	    ),
160	  );
161	
162	const CURSE_SURCHARGE_PERCENT = 50;
163	
164	const HIGH_ENCHANTMENT_LEVEL = 5;
165	
166	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
167	
168	const isHighlyEnchanted = (item: Item): boolean =>
169	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
170	
171	const isCursed = (item: Item): boolean => item.cursed === true;
172	
173	type ItemSurchargeRule = {
174	  applies: (item: Item) => boolean;
175	  percent: number;
176	};
177	
178	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
179	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
180	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
181	];
182	
183	// Item-scoped surcharges are charged on the item's own base premium, so they
184	// must NOT go through applyPolicyModifiers.
185	const itemSurcharges = (item: Item): number =>
186	  sumOf(
187	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
188	      percentOf(itemBasePremium(item), rule.percent),
189	    ),
190	  );
191	
192	const policyItemSurcharges = (items: Item[]): number =>
193	  sumOf(items.map(itemSurcharges));
194	
195	const quotePremium = (request: QuoteRequest): number =>
196	  roundPremiumInMHPCOsFavor(
197	    applyPolicyModifiers(policyBasePremium(request.items), request) +
198	      policyItemSurcharges(request.items) +
199	      PROCESSING_FEE,
200	  );
201	
202	// --- Claims -----------------------------------------------------------------
203	// An item's insurance value is what it is worth if destroyed, and is unrelated
204	// to its premium: the premium is what the customer pays to be covered. The two
205	// tables below happen to agree on a 10x ratio today, but that is a property of
206	// the current price list and not a rule of the domain — repricing premiums must
207	// not silently revalue payouts, so they stay separate.
208	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
209	  sword: 1000,
210	  amulet: 600,
211	  staff: 800,
212	  potion: 400,
213	  rune: 250,
214	  moonstone: 250,
215	};
216	
217	const insuranceSum = (items: Item[]): number =>
218	  sumOf(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
219	
220	// A policy pays out at most twice what it insures.
221	const CAP_MULTIPLIER = 2;
222	
223	const policyCap = (items: Item[]): number =>
224	  CAP_MULTIPLIER * insuranceSum(items);
225	
226	const DEDUCTIBLE = 100;
227	
228	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
229	
230	const HALF_REIMBURSEMENT_PERCENT = 50;
231	
232	const isHalfReimbursed = (item: Item): boolean =>
233	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
234	
235	const DRAGON_MATERIAL = "dragon";
236	
237	const isDragonMaterial = (item: Item): boolean =>
238	  item.material === DRAGON_MATERIAL;
239	
240	const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
241	  insuredItems.find((item) => item.type === damage.itemType);
242	
243	const FULL_REIMBURSEMENT_PERCENT = 100;
244	
245	// A reimbursement clause pays a stated percentage of the damage. Clauses are
246	// listed in precedence order and the first applicable one wins.
247	type ReimbursementClause = {
248	  applies: (item: Item) => boolean;
249	  percent: number;
250	};
251	
252	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
253	  // Half reimbursement outranks the dragon clause: the spec's "50 % rule wins"
254	  // example is a dragon-material item enchanted to 8, and it pays out half.
255	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
256	  // "Damage to items made of dragon material is fully reimbursed." This clause
257	  // is currently indistinguishable from the fallback below — every example it
258	  // matches would reimburse in full anyway, so removing it would not change a
259	  // single result, and no test can tell it is here. It is stated regardless
260	  // because it is a rule the domain asserts about dragon material, not an
261	  // accident of what the other rules happen to leave over. Should a future rule
262	  // ever reduce reimbursement below 100 % for some other reason, dragon items
263	  // must keep their full payout, and this line is what will say so.
264	  { applies: isDragonMaterial, percent: FULL_REIMBURSEMENT_PERCENT },
265	];
266	
267	// No insured item means no clause applies. That an unmatched damage reimburses
268	// in full is not a rule of the domain, only the current default: the pending
269	// "item not part of the policy" test will reject such a claim outright.
270	const reimbursementPercent = (item: Item | undefined): number =>
271	  (item === undefined
272	    ? undefined
273	    : REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent) ??
274	  FULL_REIMBURSEMENT_PERCENT;
275	
276	// What a damage entry reimburses before the deductible: a percentage of the
277	// damage amount, decided by the clauses covering the damaged item.
278	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
279	  percentOf(
280	    damage.amount,
281	    reimbursementPercent(damagedItem(insuredItems, damage)),
282	  );
283	
284	// The deductible applies once per damage event, i.e. per entry in `damages`,
285	// and always last — after the clause has decided the reimbursable amount.
286	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
287	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
288	
289	// --- Running a scenario ------------------------------------------------------
290	
291	const isQuote = (step: Step): boolean => step.op === "quote";
292	
293	// What the scenario has accumulated so far. Steps are folded rather than mapped
294	// because a step's result depends on the steps before it: `precedingQuoteCount`
295	// drives the follow-up discount today, and claim steps will thread a remaining
296	// cap through the same carry.
297	type ScenarioState = {
298	  results: StepResult[];
299	  precedingQuoteCount: number;
300	  // Policies created by earlier quote steps, keyed by that step's index — a
301	  // claim names its policy that way (`step.policy`).
302	  policiesByStep: Map<number, Item[]>;
303	};
304	
305	const INITIAL_STATE: ScenarioState = {
306	  results: [],
307	  precedingQuoteCount: 0,
308	  policiesByStep: new Map(),
309	};
310	
311	// Running a step is a state transition: it reads the carry accumulated by the
312	// preceding steps and returns the next carry. Every step kind gets its own
313	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
314	// will be added without touching the quote path.
315	type StepRunner = (
316	  customer: Customer,
317	  state: ScenarioState,
318	  step: Step,
319	  stepIndex: number,
320	) => ScenarioState;
321	
322	const appendResult = (
323	  state: ScenarioState,
324	  result: StepResult,
325	): ScenarioState => ({ ...state, results: [...state.results, result] });
326	
327	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
328	  const items = step.items ?? [];
329	
330	  const premium = quotePremium({
331	    customer,
332	    items,
333	    precedingQuoteCount: state.precedingQuoteCount,
334	  });
335	
336	  return {
337	    ...appendResult(state, { premium }),
338	    precedingQuoteCount: state.precedingQuoteCount + 1,
339	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, items),
340	  };
341	};
342	
343	// A claim names its policy by the index of the quote step that created it. An
344	// unnamed or unknown policy currently yields no insured items, and so a cap of
345	// 0 — the pending error-handling tests will replace this with a rejection.
346	const insuredItemsFor = (state: ScenarioState, step: Step): Item[] =>
347	  step.policy === undefined ? [] : (state.policiesByStep.get(step.policy) ?? []);
348	
349	const runClaimStep: StepRunner = (_customer, state, step) => {
350	  const damages = step.incident?.damages ?? [];
351	  const insuredItems = insuredItemsFor(state, step);
352	
353	  const payout = sumOf(
354	    damages.map((damage) => damagePayout(insuredItems, damage)),
355	  );
356	  const cap = policyCap(insuredItems);
357	
358	  return appendResult(state, { payout, remainingCap: cap - payout });
359	};
360	
361	const runStep: StepRunner = (customer, state, step, stepIndex) =>
362	  isQuote(step)
363	    ? runQuoteStep(customer, state, step, stepIndex)
364	    : runClaimStep(customer, state, step, stepIndex);
365	
366	// The customer is scenario-wide, so it is closed over rather than threaded
367	// through the fold alongside the per-step state.
368	const stepRunnerFor =
369	  (customer: Customer) =>
370	  (state: ScenarioState, step: Step, stepIndex: number) =>
371	    runStep(customer, state, step, stepIndex);
372	
373	export const runScenario = (scenario: Scenario): ScenarioResults => ({
374	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
375	    .results,
376	});
